WITH remaining_keys AS (SELECT id FROM promotions EXCEPT SELECT id FROM promotions WHERE channel NOT IN ('mobile', 'partner')), kept_rows AS (SELECT s.* FROM promotions s JOIN remaining_keys k ON s.id = k.id) SELECT id, channel, CASE WHEN channel RLIKE '^(partner|mobile)$' THEN 'GROUP_B' WHEN channel RLIKE '^(web|store)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS channel_zone FROM kept_rows ORDER BY channel NULLS FIRST;
